// VITE CONFIG: tells the build which HTML pages to include.
// Pages are found automatically: work.html + projects/index.html + projects/<slug>/index.html
// (the project pages are generated by: npm run projects)
import { defineConfig } from 'vite';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(fileURLToPath(import.meta.url));

const input = { work: path.join(root, 'work.html') };

const projectsDir = path.join(root, 'projects');
if (fs.existsSync(projectsDir)) {
  const listPage = path.join(projectsDir, 'index.html');
  if (fs.existsSync(listPage)) input.projects = listPage;
  for (const d of fs.readdirSync(projectsDir, { withFileTypes: true })) {
    const page = path.join(projectsDir, d.name, 'index.html');
    if (d.isDirectory() && fs.existsSync(page)) input['project-' + d.name] = page;
  }
}

export default defineConfig({
  build: { rollupOptions: { input } },
});